'use strict';
const $=id=>document.getElementById(id), pages=window.PAGES;
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const save=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{}};
let favorites=new Set(read('ce2-favorites',[])),last=read('ce2-last',null),category='Tout',onlyFavorites=false,current=0,zoom=100,mode='photo';
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const summaries=pages.filter(p=>p.category==='Sommaires'), lessons=pages.filter(p=>p.category!=='Sommaires');
const readingGroup=()=>pages[current].category==='Sommaires'?summaries:lessons;
const searchIndex=pages.map(p=>normalize([p.title,p.category,...p.lines].join(' ')));
const el=(tag,className,text)=>{const n=document.createElement(tag);if(className)n.className=className;if(text!==undefined)n.textContent=text;return n};
const categories=['Tout','Grammaire','Conjugaison','Vocabulaire','Orthographe','Numération','Calcul','Géométrie','Mesures','Problèmes'];
for(const cat of categories){const b=el('button','',cat);b.setAttribute('aria-pressed',cat===category);b.onclick=()=>{category=cat;for(const node of $('filters').children)node.setAttribute('aria-pressed',node===b);render()};$('filters').append(b)}
function toggleFavorite(id){favorites.has(id)?favorites.delete(id):favorites.add(id);save('ce2-favorites',[...favorites]);render();updateBookmark()}
function render(){const words=normalize($('search').value.trim()).split(/\s+/).filter(Boolean);const selected=pages.filter((p,i)=>p.category!=='Sommaires'&&(category==='Tout'||p.category===category)&&(!onlyFavorites||favorites.has(p.id))&&words.every(w=>searchIndex[i].includes(w)));$('grid').replaceChildren();$('count').textContent=lessons.length+' pages';$('results-info').textContent=selected.length+' photo'+(selected.length>1?'s':'')+(onlyFavorites?' dans mes favoris':' à explorer');$('empty').hidden=selected.length>0;
 for(const p of selected){const card=el('article','card'+(favorites.has(p.id)?' saved':'')),open=el('button','card-open'),visual=el('div','thumbnail'),img=el('img');img.src='thumbs/'+p.file+'?v=scan-20260911';img.alt='';img.loading='lazy';img.width=250;img.height=350;visual.append(img,el('span','photo-no',String(p.id-218).padStart(2,'0')));const copy=el('div','card-copy');copy.append(el('p','category',p.category),el('h3','',p.title));open.append(visual,copy);open.setAttribute('aria-label','Lire : '+p.title);open.onclick=()=>{openPage(p.id);setMode('photo')};const bottom=el('div','card-bottom');const exercise=el('button','exercise-link');const result=window.Quiz.result(p.id);exercise.textContent=result?(result.score===result.total?'✓ Exercice réussi':`À revoir · ${result.score}/${result.total}`):`Exercice · ${window.QUIZZES[p.id].length} questions`;exercise.setAttribute('aria-label','Faire l’exercice : '+p.title);exercise.onclick=()=>{openPage(p.id);setMode('quiz')};bottom.append(exercise);const star=el('button','star',favorites.has(p.id)?'♥':'♡');star.setAttribute('aria-label',(favorites.has(p.id)?'Retirer des favoris : ':'Ajouter aux favoris : ')+p.title);star.setAttribute('aria-pressed',favorites.has(p.id));star.onclick=()=>toggleFavorite(p.id);bottom.append(star);card.append(open,bottom);$('grid').append(card)}
}
function updateBookmark(){const on=favorites.has(pages[current].id);$('bookmark').textContent=on?'♥ Favori':'♡ Favori';$('bookmark').setAttribute('aria-pressed',on)}
function setZoom(value){zoom=Math.max(100,Math.min(300,value));$('page-image').style.width=zoom+'%';$('zoom-reset').textContent=zoom+' %';$('zoom-out').disabled=zoom===100;$('zoom-in').disabled=zoom===300}
function setMode(value){if(value==='quiz'&&!window.QUIZZES[pages[current].id])value='photo';mode=value;$('quiz-view').hidden=value!=='quiz';$('quiz-tab').setAttribute('aria-pressed',value==='quiz');if(value==='quiz')window.Quiz.render(pages[current].id);$('photo-view').hidden=value!=='photo';$('zoom-tools').hidden=value!=='photo';$('photo-tab').setAttribute('aria-pressed',value==='photo')}
function openPage(id,hash=true){const idx=pages.findIndex(p=>p.id===Number(id));if(idx<0)return;current=idx;const p=pages[idx],group=readingGroup(),groupIndex=group.findIndex(item=>item.id===p.id);$('jump').replaceChildren(...group.map(item=>{const option=el('option','',item.category==='Sommaires'?item.title.replace('Sommaire · ',''):String(item.id-218));option.value=item.id;return option}));$('title').textContent=p.title;$('subject').textContent=p.category;$('position').textContent=(groupIndex+1)+' / '+group.length;$('page-image').src='photos/'+p.file+'?v=scan-20260911';$('page-image').alt='Photo '+(idx+1)+' : '+p.title;$('prev').disabled=groupIndex===0;$('next').disabled=groupIndex===group.length-1;$('jump').value=String(p.id);$('quiz-tab').hidden=!window.QUIZZES[p.id];setMode(mode);setZoom(100);updateBookmark();last=p.id;save('ce2-last',last);updateResume();if(!$('reader').open){$('reader').showModal();document.body.classList.add('reading')}$('reader').scrollTop=0;$('photo-view').scrollLeft=0;if(hash)history.replaceState(null,'','#photo-'+p.id)}
function updateResume(){$('resume').hidden=!pages.some(p=>p.id===last)}
function closeReader(){if($('reader').open)$('reader').close();document.body.classList.remove('reading');history.replaceState(null,'',location.pathname+location.search)}
for(const p of summaries){const button=el('button','summary-card');const image=el('img');image.src='thumbs/'+p.file+'?v=scan-20260911';image.alt='';image.width=60;image.height=80;const label=el('span','',p.title.replace('Sommaire · ',''));button.append(image,label,el('span','summary-arrow','↗'));button.onclick=()=>openPage(p.id);$('summary-links').append(button)}
$('search').addEventListener('input',render);$('favorites').onclick=()=>{onlyFavorites=!onlyFavorites;$('favorites').setAttribute('aria-pressed',onlyFavorites);render();$('collection-title').scrollIntoView({behavior:'smooth',block:'start'})};$('resume').onclick=()=>openPage(last);$('close').onclick=closeReader;$('reader').addEventListener('cancel',e=>{e.preventDefault();closeReader()});$('bookmark').onclick=()=>toggleFavorite(pages[current].id);$('prev').onclick=()=>{const group=readingGroup(),index=group.findIndex(p=>p.id===pages[current].id);if(index>0)openPage(group[index-1].id)};$('next').onclick=()=>{const group=readingGroup(),index=group.findIndex(p=>p.id===pages[current].id);if(index<group.length-1)openPage(group[index+1].id)};$('jump').onchange=e=>openPage(e.target.value);$('zoom-in').onclick=()=>setZoom(zoom+50);$('zoom-out').onclick=()=>setZoom(zoom-50);$('zoom-reset').onclick=()=>setZoom(100);$('quiz-tab').onclick=()=>setMode('quiz');$('photo-tab').onclick=()=>setMode('photo');
document.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if($('reader').open){if(mode==='quiz')return;if(e.key==='ArrowLeft')$('prev').click();if(e.key==='ArrowRight')$('next').click()}else if(e.key==='/'){e.preventDefault();$('search').focus()}});
window.addEventListener('hashchange',()=>{const match=location.hash.match(/^#photo-(\d+)$/);if(match)openPage(match[1],false);else closeReader()});
document.addEventListener('ce2-quiz-update',render);
render();updateResume();const initial=location.hash.match(/^#photo-(\d+)$/);if(initial)openPage(initial[1],false);
